import type {
  EmptyStateProps,
  EmptyStateIconProps,
  EmptyStateTitleProps,
  EmptyStateContentProps,
  EmptyStateDescriptionProps,
  EmptyStateActionsProps,
  EmptyStateFooterTextProps,
} from "./empty-state.types";

import { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { PolymorphicRef } from "src/types/component";

import { EmptyStateClasses, StyledEmptyState } from "./empty-state.styles";

const EmptyStateRoot = forwardRef<HTMLDivElement, EmptyStateProps>(
  (
    { children, className, size = "default", variant = "default", ...props }: EmptyStateProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme(),
      rootClasses = clsx(EmptyStateClasses.root, className, {
        [EmptyStateClasses.sm]: size === "sm",
      });

    return (
      <StyledEmptyState
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledEmptyState>
    );
  },
);

EmptyStateRoot.displayName = "EmptyState";

const EmptyStateIcon = forwardRef<HTMLDivElement, EmptyStateIconProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(EmptyStateClasses.image, className)} {...props}>
        {children}
      </div>
    );
  },
);

EmptyStateIcon.displayName = "EmptyState.Icon";

const EmptyStateContent = forwardRef<HTMLDivElement, EmptyStateContentProps>(
  ({ children, className, ...props }, ref) => {
    const contentClasses = clsx(EmptyStateClasses.content, className);
    return (
      <div ref={ref} className={contentClasses} {...props}>
        {children}
      </div>
    );
  },
);
EmptyStateContent.displayName = "EmptyState.Content";

const EmptyStateTitle = forwardRef(function EmptyStateTitle<C extends React.ElementType = "h3">(
  { children, className, as, ...props }: EmptyStateTitleProps<C>,
  ref: PolymorphicRef,
) {
  const titleClasses = clsx(EmptyStateClasses.title, className);
  const Component = as || "h3";
  return (
    <Component ref={ref} className={titleClasses} {...props}>
      {children}
    </Component>
  );
});
EmptyStateTitle.displayName = "EmptyState.Title";

const EmptyStateDescription = forwardRef<HTMLParagraphElement, EmptyStateDescriptionProps>(
  ({ children, className, ...props }, ref) => {
    const descriptionClasses = clsx(EmptyStateClasses.description, className);
    return (
      <p ref={ref} className={descriptionClasses} {...props}>
        {children}
      </p>
    );
  },
);
EmptyStateDescription.displayName = "EmptyState.Description";

const EmptyStateActions = forwardRef<HTMLDivElement, EmptyStateActionsProps>(
  ({ children, className, ...props }, ref) => {
    const actionsClasses = clsx(EmptyStateClasses.actions, className);
    return (
      <div ref={ref} className={actionsClasses} {...props}>
        {children}
      </div>
    );
  },
);
EmptyStateActions.displayName = "EmptyState.Actions";

const EmptyStateFooterText = forwardRef<HTMLDivElement, EmptyStateFooterTextProps>(
  ({ children, className, ...props }, ref) => {
    const footerTextClasses = clsx(EmptyStateClasses.footerText, className);
    return (
      <div ref={ref} className={footerTextClasses} {...props}>
        {children}
      </div>
    );
  },
);
EmptyStateFooterText.displayName = "EmptyState.FooterText";

const EmptyState = Object.assign(EmptyStateRoot, {
  Icon: EmptyStateIcon,
  Content: EmptyStateContent,
  Title: EmptyStateTitle,
  Description: EmptyStateDescription,
  Actions: EmptyStateActions,
  FooterText: EmptyStateFooterText,
});

export default EmptyState;
